    function expenseOverview(r){const s=r.summary||{},ms=arr(r.monthly_detail).filter(x=>String(x.month)>=expenseRange(st.expense.key).from.slice(0,7)),last=ms[ms.length-1]||{},prev=ms[ms.length-2]||{},cats=arr(r.rankings?.categories);return '<div class="v167-kpis">'+kpi('Total do período',s.selected_total,expenseRange(st.expense.key).label,'primary')+kpi('Média mensal',s.monthly_average,(r.period?.months_in_selection||ms.length)+' meses')+kpi('Mês atual',last.total,last.is_partial?'parcial até '+date(r.period?.last_available):'mês fechado')+kpi('Cartões',s.card_total,'consumo consolidado')+kpi('Contas',s.account_total,'pagamentos fora de cartão')+'</div><div class="v167-grid two"><article class="v167-card"><div class="v167-cardhead"><div><span>Evolução</span><h2>Despesa mês a mês</h2></div><small>'+date(r.period?.from)+' → '+date(r.period?.to)+'</small></div>'+barChart(ms)+'</article><article class="v167-card"><div class="v167-cardhead"><div><span>Leitura rápida</span><h2>Comparações</h2></div></div><div class="v167-statlist"><div class="v167-stat"><span>Mês anterior</span><b>'+money(prev.total)+'</b></div><div class="v167-stat"><span>Variação mensal</span><b>'+pct(last.mom_comparison_pct)+'</b></div><div class="v167-stat"><span>Últimos 12 meses</span><b>'+money(s.last_12m)+'</b></div><div class="v167-stat"><span>Histórico analisado</span><b>'+money(s.history_total)+'</b></div></div><div class="v167-note"><b>Período ativo:</b> todos os números e gráficos desta tela usam a seleção acima.</div></article></div><article class="v167-card"><div class="v167-cardhead"><div><span>Composição</span><h2>Maiores grupos</h2></div><button class="v167-btn" data-v167-exp-tab="categories">Ver categorias</button></div>'+rankRows(cats,10)+'</article>'}
    function expenseCategories(r){const cats=arr(r.rankings?.categories),centers=arr(r.rankings?.centers),ben=centers.find(x=>norm(x.name)==='benjamin'),edu=cats.find(x=>norm(x.name)==='educacao');return '<div class="v167-grid two"><article class="v167-card"><div class="v167-cardhead"><div><span>Categorias</span><h2>Para onde foi o dinheiro</h2></div><strong>'+money(r.summary?.selected_total)+'</strong></div>'+rankRows(cats,25)+'</article><div class="v167-grid"><article class="v167-card"><div class="v167-cardhead"><div><span>Família</span><h2>Benjamin</h2></div></div><div class="v167-family"><i>B</i><div><b>Benjamin</b><span>grupo de acompanhamento</span></div><strong>'+money(ben?.total)+'</strong></div><div class="v167-statlist"><div class="v167-stat"><span>Educação</span><b>'+money(edu?.total)+'</b></div><div class="v167-stat"><span>Total atribuído a Benjamin</span><b>'+money(ben?.total)+'</b></div></div></article><article class="v167-card"><div class="v167-cardhead"><div><span>Pessoas e contextos</span><h2>Centros de acompanhamento</h2></div></div>'+rankRows(centers.filter(x=>norm(x.name)!=='nao atribuido'),12)+'</article></div></div>'}
    function cardAccount(name){const n=norm(name);if(n.includes('aeternum')||n.includes('bradesco'))return'Bradesco';if(n.includes('c6')||n.includes('carbon'))return'C6';if(n.includes('personnalite')||n.includes('mastercard')||n.includes('itau'))return'Itaú';return''}
    function cardDisplayRows(){const o=D?.card_operating||{},live=[...arr(o.open_cycles).map(x=>({...x,date:x.due_date,status:'Fatura aberta',live:true})),...arr(o.closed_or_due).map(x=>({...x,date:x.due_date,status:x.state==='payment_evidence_needed'?'Pagamento a confirmar':'Fatura fechada',live:true})),...arr(o.paid_recent).map(x=>({...x,date:x.payment_date||x.due_date,status:'Pagamento documentado',live:true}))],history=arr(st.invoices.rows).map(x=>({...x,status:'Histórico do Fluxo'})),seen=new Set(),out=[];for(const x of [...live,...history].sort((a,b)=>String(b.date||b.event_date).localeCompare(String(a.date||a.event_date)))){const key=[String(x.date||x.event_date).slice(0,10),Math.abs(num(x.amount)||0).toFixed(2),norm(x.card_name||x.description||'')].join('|');if(seen.has(key))continue;seen.add(key);out.push(x)}st.invoices.display=out;return out}
    function detailCategories(rows){const m=new Map();for(const x of arr(rows)){const key=x.category||x.category_lts||'A classificar';m.set(key,(m.get(key)||0)+(num(x.amount)||0))}return[...m].map(([name,total])=>({name,total})).sort((a,b)=>b.total-a.total)}
    function showInvoiceDetail(x,j){const purchases=arr(j?.purchases?.length?j.purchases:x.detail_preview).map(p=>({...p,category:p.category||p.category_lts||'A classificar'})),cats=detailCategories(purchases),total=num(j?.invoice_total??x.amount),pending=purchases.filter(p=>norm(p.category)==='a classificar').length,title=j?.card_name||x.card_name||x.description||'Fatura';const bg=modal(title,(x.status||'Fatura')+' · '+date(j?.due_date||x.due_date||x.date||x.event_date),'<div class="v167-kpis">'+kpi('Total da fatura',total,'valor observado','primary')+kpiText('Itens documentados',purchases.length,'compras disponíveis')+kpiText('A classificar',pending,pending?'revisão necessária':'itens classificados')+'</div><div class="v167-grid equal" style="margin-top:12px"><article class="v167-card"><div class="v167-cardhead"><div><span>Composição</span><h2>Por categoria</h2></div></div>'+rankRows(cats,30)+'</article><article class="v167-card"><div class="v167-cardhead"><div><span>Conciliação</span><h2>Leitura da fatura</h2></div></div><div class="v167-statlist"><div class="v167-stat"><span>Vencimento</span><b>'+date(j?.due_date||x.due_date||x.date)+'</b></div><div class="v167-stat"><span>Detalhe × total</span><b>'+(purchases.length?(j?.cash_reconciled===false?'Em revisão':'Disponível'):'Não documentado')+'</b></div><div class="v167-stat"><span>Situação</span><b>'+esc(x.status||'Fatura')+'</b></div></div></article></div><div class="v167-tablewrap" style="margin-top:12px"><table class="v167-table"><thead><tr><th>Compra</th><th>Categoria</th><th>Parcela</th><th class="num">Valor</th></tr></thead><tbody>'+(purchases.map(p=>'<tr><td>'+esc(p.description||'Compra')+'</td><td>'+esc(p.category)+'</td><td>'+esc(p.installment||p.installment_label||(p.installments>1?(p.installment_number||'—')+'/'+p.installments:'—'))+'</td><td class="num">'+money(p.amount)+'</td></tr>').join('')||'<tr><td colspan="4">O total está preservado, mas esta competência ainda não tem compras individualizadas.</td></tr>')+'</tbody></table></div>'+(x.source?'<div style="margin-top:12px"><button class="v167-btn blue" id="v167InvoiceFlow">Abrir esta fatura no Fluxo</button></div>':'')+'<div class="v167-note" style="margin-top:12px">Pagamento de fatura explica o caixa; cada compra explica o consumo uma única vez.</div>');bg.querySelector('#v167InvoiceFlow')?.addEventListener('click',()=>{bg.remove();openInFlow(x,false)})}
    async function openInvoiceDetail(x,button){if(!x)return;button.disabled=true;const old=button.textContent;button.textContent='Carregando…';try{if(arr(x.detail_preview).length)return showInvoiceDetail(x,{matched:true,invoice_total:x.amount,due_date:x.due_date,purchases:x.detail_preview});const j=await rpc('lts_browser_card_settlement_detail_v2',{p_event_date:String(x.date||x.event_date||x.due_date).slice(0,10),p_description:x.description||('Fatura '+(x.card_name||'')),p_amount:Math.abs(num(x.amount)||0),p_account:x.account||cardAccount(x.card_name)});showInvoiceDetail(x,j||{})}catch(e){toast2('Não foi possível abrir a composição: '+String(e?.message||e))}finally{button.disabled=false;button.textContent=old}}
    function expenseCards(){ensureInvoices();const s=st.invoices,o=D?.card_operating||{},rows=cardDisplayRows(),pending=num(o.classification_review?.pending_lines)||0;return '<div class="v167-grid"><div class="v167-kpis">'+kpi('Faturas abertas',o.open_cycles_total,arr(o.open_cycles).length+' ciclo(s)','primary')+kpi('Vencidas / a confirmar',o.closed_or_due_total,arr(o.closed_or_due).length+' ciclo(s)')+kpi('Parcelas futuras',o.contracted_installment_floor_total,'piso já contratado')+kpi('A classificar',pending,'itens documentados')+'</div><article class="v167-card"><div class="v167-cardhead"><div><span>Cartões e faturas</span><h2>Faturas consideradas no Fluxo</h2></div><small>'+rows.length+' registro(s)</small></div>'+(s.loading?loading():s.error?errorBox(s.error):'<div class="v167-invoices">'+(rows.map((x,i)=>'<div class="v167-invoice"><span>'+date(x.date||x.event_date||x.due_date)+'</span><div><b>'+esc(x.card_name||x.description||'Fatura')+'</b><small>'+esc(x.status||'Fatura')+' · '+esc(x.account||cardAccount(x.card_name)||'')+(arr(x.detail_preview).length?' · '+arr(x.detail_preview).length+' itens':'')+'</small></div><strong>'+money(Math.abs(num(x.amount)||0))+'</strong><div class="v167-searchactions"><button class="v167-btn primary" data-v167-invoice-detail="'+i+'">Ver composição</button>'+(x.source?'<button class="v167-btn" data-v167-flow-row="invoice-display:'+i+'">Fluxo</button>':'')+'</div></div>').join('')||'<div class="v167-empty">Nenhuma fatura encontrada.</div>')+'</div>')+'<div class="v167-note"><b>Bradesco de R$ 29,90:</b> classificado como Assinaturas. O pagamento explica o caixa; compras classificadas explicam o consumo, sem dupla contagem.</div></article></div>'}
    function expenseTransactions(){ensureTransactions();const s=st.transactions,rows=arr(s.rows);return '<article class="v167-card"><div class="v167-cardhead"><div><span>Lançamentos</span><h2>Despesas do período</h2></div><button class="v167-btn" data-v167-go="Atualizações" data-focus="search">Pesquisar todo o histórico</button></div>'+(s.loading?loading():s.error?errorBox(s.error):'<div class="v167-tablewrap"><table class="v167-table"><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Conta/cartão</th><th class="num">Valor</th><th></th></tr></thead><tbody>'+rows.map((x,i)=>'<tr><td>'+date(x.date||x.event_date)+'</td><td><b>'+esc(x.description||x.counterparty||'Lançamento')+'</b></td><td>'+esc(x.category||'A classificar')+'</td><td>'+esc(x.account||x.card_name||'—')+'</td><td class="num">'+money(Math.abs(num(x.amount)||0))+'</td><td><button class="v167-btn" data-v167-flow-row="transaction:'+i+'">Abrir</button></td></tr>').join('')+'</tbody></table></div>')+'</article>'}
    function despesasV167(){ensureExpense();const s=st.expense,r=s.data||{},meta=sourceLabel(r.period?.last_available||today())+periodButtons();let body=s.loading&&!s.data?loading():s.error&&!s.data?errorBox(s.error):s.tab==='categories'?expenseCategories(r):s.tab==='cards'?expenseCards():s.tab==='transactions'?expenseTransactions():expenseOverview(r);return '<div class="v167 v167-expenses">'+head('Despesas','Despesas','Consumo, cartões e lançamentos com período explícito e sem dupla contagem.',meta)+expenseTabs()+body+'</div>'}

    function wealthTabs(){return tabs([['overview','Visão geral'],['rsu','RSUs e awards'],['assets','Bens e dívidas'],['pensions','Previdências']],st.wealth.tab,'data-v167-wealth-tab')}
    function wealthOverview(j){const w=j.wealth||{},s=w.summary||{},x=j.wealth_v167||{},p=j.pensions||{},r=j.rsu_summary||{},c=w.assets?.cipo_396||{},v=w.assets?.volvo_xc40||{},dist=[{name:'CIPÓ 396',total:c.market_central},{name:'Volvo XC40',total:v.market_central},{name:'RSUs e corretora',total:r.available_total_brl},{name:'Previdências',total:p.total_gross_brl},{name:'Liquidez bancária e D0',total:(num(w.liquidity?.bank_cash)||0)+(num(w.liquidity?.d0)||0)}];return '<div class="v167-kpis">'+kpi('Patrimônio líquido central',x.net_worth_central_including_pensions??s.net_worth_central,'inclui previdências brutas','primary')+kpi('Ativos',x.assets_central_including_pensions??s.assets_central,'valor central')+kpi('Dívidas conhecidas',s.known_debt_total,'saldos documentados')+kpi('Liquidez até D+3',s.liquidity_through_d3,'FGTS e previdências separados')+kpi('Previdências',p.total_gross_brl,'restritas · valor bruto')+'</div><div class="v167-grid equal"><article class="v167-card"><div class="v167-cardhead"><div><span>Composição</span><h2>Onde está o patrimônio</h2></div></div>'+rankRows(dist,8)+'</article><article class="v167-card"><div class="v167-cardhead"><div><span>Posições principais</span><h2>Ativos e acesso ao dinheiro</h2></div></div><div class="v167-statlist"><div class="v167-stat"><span>CIPÓ 396<small>mercado central · dívida '+money(c.documentary_debt)+'</small></span><b>'+money(c.market_central)+'</b></div><div class="v167-stat"><span>Volvo XC40<small>mercado central · financiado '+money(v.documented_financed_balance)+'</small></span><b>'+money(v.market_central)+'</b></div><div class="v167-stat"><span>RSUs + saldo em corretora<small>posição disponível em '+date(r.as_of)+'</small></span><b>'+money(r.available_total_brl)+'</b></div><div class="v167-stat"><span>Previdências<small>restritas · saldos brutos</small></span><b>'+money(p.total_gross_brl)+'</b></div><div class="v167-stat"><span>Schiavalli<small>posição documental ainda não localizada</small></span><b>—</b></div></div></article></div>'}
    function awardType(x){return /cash/i.test(String(x.asset_type||''))?'Cash RSU':'RSU'}
    function rsuPanel(j){const r=j.rsu_summary||{},rows=arr(j.rsu?.future_schedule),ret=j.employment_awards?.retention||{};return '<div class="v167-kpis">'+kpi('Já vested · ações',r.vested_shares_brl,date(r.as_of),'primary')+kpi('Saldo em corretora',r.brokerage_cash_brl,date(r.as_of))+kpi('Total disponível',r.available_total_brl,'ações + saldo')+kpi('RSUs futuras',r.future_regular_brl,'100% bruto')+kpi('Cash RSUs futuras',r.future_cash_net_brl,'70% após reserva fiscal')+'</div><article class="v167-card"><div class="v167-cardhead"><div><span>Agenda</span><h2>Vestings e disponibilidade</h2></div><strong>'+money(r.future_considered_total_brl)+'</strong></div><div class="v167-awards">'+rows.map((x,i)=>{const type=awardType(x),value=type==='Cash RSU'?x.net_value_brl:x.gross_value_brl;return '<div class="v167-award"><div><span>Vesting</span><b>'+date(x.eligibility_date)+'</b><small>'+esc(type)+'</small></div><div><span>Quantidade</span><b>'+number(x.quantity)+'</b></div><div><span>Cotação usada</span><b>'+usd(x.unit_price_usd)+'</b><small>câmbio '+fx(x.fx_rate)+'</small></div><div><span>Valor considerado</span><b>'+money(value)+'</b><small>'+date(x.available_date)+' disponível</small></div><label><span>Antecipação opcional</span><input type="date" data-v167-award-date="'+i+'" max="'+esc(x.eligibility_date)+'" value="'+esc(x.anticipated_date||'')+'"></label><div><button class="v167-btn" data-v167-award-edit="'+i+'">Cotação</button> <button class="v167-btn blue" data-v167-award-save="'+i+'">Salvar data</button></div></div>'}).join('')+'</div><div class="v167-note"><b>Datas diferentes:</b> vesting é o direito adquirido; disponibilidade é a data em que entra na liquidez. O Fluxo agora mostra os dois marcos.</div></article><article class="v167-card"><div class="v167-cardhead"><div><span>Retention Award</span><h2>Acordo separado de RSU</h2></div><strong>'+money(ret.gross_total_brl)+'</strong></div><div class="v167-note">As parcelas permanecem separadas de RSU e Cash RSU. Tributação líquida não é presumida sem documento.</div></article>'}
    function commitmentBy(j,id){return arr(j.financing?.summary?.commitments).find(x=>x.id===id)||{}}
    function docBy(j,id){return arr(j.financing?.documentary?.items).filter(x=>x.commitment_id===id).sort((a,b)=>arr(b.schedule_loaded?.rows).length-arr(a.schedule_loaded?.rows).length)[0]||{}}
    function loanCard(j,id,label,type){const c=commitmentBy(j,id),doc=docBy(j,id),meta=doc.metadata||{},total=num(c.total_events??meta.total_installments??(id==='cipo_396'?meta.term_total:null)),remaining=num(c.remaining_events??meta.remaining_installments??doc.schedule_loaded?.remaining_loaded),paid=num(meta.paid_installments)??(total!=null&&remaining!=null?Math.max(0,total-remaining):null),progress=total?clamp((paid||0)/total*100,0,100):0,balance=num(c.current_documentary_debt_balance??doc.debt_balance),future=num(c.remaining_scheduled_outflow_current_terms??c.remaining_scheduled_outflow??c.remaining_economic_outflow??doc.schedule_loaded?.future_loaded_total);return '<article class="v167-loan"><span>'+esc(type)+'</span><h3>'+esc(label)+'</h3><div class="v167-loanmetrics"><div><span>Saldo atual</span><b>'+money(balance)+'</b></div><div><span>Saídas futuras</span><b>'+money(future)+'</b></div><div><span>Pagas</span><b>'+(paid==null?'—':paid)+'</b></div><div><span>Restantes</span><b>'+(remaining==null?'—':remaining)+'</b></div></div><div class="v167-progress"><i style="width:'+progress+'%"></i></div><div class="v167-asof">Atualizado em '+date(c.current_debt_as_of||doc.as_of_date||c.first_date)+'</div><div style="margin-top:10px"><button class="v167-btn" data-v167-loan="'+id+'">Ver parcelas e detalhes</button></div></article>'}
    function assetsPanel(j){const w=j.wealth||{},c=w.assets?.cipo_396||{},v=w.assets?.volvo_xc40||{},r=j.rsu_summary||{},p=j.pensions||{};return '<div class="v167-wealthcards"><article class="v167-asset"><div class="v167-assettop"><div><span>Imóvel</span><h3>CIPÓ 396</h3></div><div class="v167-asof">Patrimônio líquido em '+date(commitmentBy(j,'cipo_396').current_debt_as_of)+'</div></div><strong>'+money(c.equity_central)+'</strong><div class="v167-facts"><div class="v167-fact"><span>Mercado central</span><b>'+money(c.market_central)+'</b></div><div class="v167-fact"><span>Saldo para quitação</span><b>'+money(c.documentary_debt)+'</b></div><div class="v167-fact"><span>Compra + reforma</span><b>'+money(c.historical_purchase_plus_reform)+'</b></div><div class="v167-fact"><span>Até o contrato*</span><b>'+money(j.cipo_detail?.contractual_outflow_current_terms_brl)+'</b><small>*termos atuais; sujeito à TR</small></div></div><div style="margin-top:10px"><button class="v167-btn" data-v167-cipo>Ver gastos da obra</button></div></article><article class="v167-asset"><div class="v167-assettop"><div><span>Veículo</span><h3>Volvo XC40</h3></div><div class="v167-asof">posição documental</div></div><strong>'+money(v.equity_central)+'</strong><div class="v167-facts"><div class="v167-fact"><span>Mercado central</span><b>'+money(v.market_central)+'</b></div><div class="v167-fact"><span>Saldo financiado</span><b>'+money(v.documented_financed_balance)+'</b></div></div></article><article class="v167-asset"><div class="v167-assettop"><div><span>Ações</span><h3>RSUs e corretora</h3></div><div class="v167-asof">'+date(r.as_of)+'</div></div><strong>'+money(r.available_total_brl)+'</strong><div class="v167-facts"><div class="v167-fact"><span>Ações vested</span><b>'+money(r.vested_shares_brl)+'</b></div><div class="v167-fact"><span>Saldo em corretora</span><b>'+money(r.brokerage_cash_brl)+'</b></div></div></article><article class="v167-asset"><div class="v167-assettop"><div><span>Previdência</span><h3>Organon + Novartis</h3></div><div class="v167-asof">bruto restrito</div></div><strong>'+money(p.total_gross_brl)+'</strong><div class="v167-note">Regime regressivo. O valor líquido depende do tempo de cada contribuição.</div></article></div><article class="v167-card"><div class="v167-cardhead"><div><span>Financiamentos e empréstimos</span><h2>Saldo, parcelas e progresso</h2></div></div><div class="v167-loans">'+loanCard(j,'cipo_396','CIPÓ 396','Financiamento imobiliário')+loanCard(j,'volvo','Volvo XC40','Financiamento de veículo')+loanCard(j,'coopharma','Coopharma','Empréstimo consignado')+loanCard(j,'pai_mae','Pai e Mãe','Empréstimo familiar')+'</div></article>'}
    function pensionsPanel(j){const p=j.pensions||{},rows=arr(p.positions);return '<div class="v167-kpis">'+kpi('Total em previdências',p.total_gross_brl,'saldos brutos restritos','primary')+kpi('Organon',rows.find(x=>/organon/i.test(x.name||''))?.gross_balance_brl,'Multiprev')+kpi('Novartis',rows.find(x=>/novartis/i.test(x.name||''))?.gross_balance_brl,'Plano D')+'</div><div class="v167-pensions">'+rows.map(x=>'<article class="v167-pension"><span>Previdência privada</span><h3>'+esc(x.name)+'</h3><strong>'+money(x.gross_balance_brl)+'</strong><dl><dt>Posição</dt><dd>'+date(x.as_of)+'</dd><dt>Regime</dt><dd>Regressivo</dd><dt>Perfil</dt><dd>'+esc(x.profile||'—')+'</dd><dt>Saldo participante</dt><dd>'+money(x.participant_balance_brl)+'</dd><dt>Saldo patrocinadora</dt><dd>'+money(x.sponsor_balance_brl)+'</dd><dt>Rentabilidade do mês</dt><dd>'+money(x.monthly_return_brl)+' · '+pct(x.monthly_return_pct)+'</dd></dl></article>').join('')+'</div><div class="v167-note warn"><b>Valor bruto, não resgate recomendado.</b> No regime regressivo, a alíquota depende da idade de cada contribuição. O LTS não calcula líquido sem esse histórico.</div>'}
    function patrimonioV167(){ensureWealth();const s=st.wealth,j=s.data||{},body=s.loading&&!s.data?loading():s.error&&!s.data?errorBox(s.error):s.tab==='rsu'?rsuPanel(j):s.tab==='assets'?assetsPanel(j):s.tab==='pensions'?pensionsPanel(j):wealthOverview(j);return '<div class="v167 v167-wealth">'+head('Patrimônio','Patrimônio','Ativos, dívidas, financiamentos, RSUs e previdências com data de posição.',sourceLabel(j.as_of||today()))+wealthTabs()+body+'</div>'}

